     &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;boutonCombat&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;Combat&#39;);&quot; onmouseout=&quot;outButton(&#39;Combat&#39;);&quot; onclick=&quot;expandMenu(&#39;Combat&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html&quot; title=&quot;Le combat de masse&quot;&gt;Le combat de masse&lt;/a&gt;
        &lt;ul ID=&quot;Combat&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Les phases d&#39;une bataille&lt;/a&gt;&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#L&#233;chelle_de_strat&#233;gie_0&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;L&#39;&#233;chelle de strat&#233;gie&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#ATTAQUERETSUBIRDESDEGATS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Attaquer et subir des d&#233;g&#226;ts&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Les conditions du champ de bataille&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#RECUPERATION&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;La r&#233;cup&#233;ration&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#PJDANSLESBATAILLES&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Les personnages joueurs dans les batailles&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;Les tactiques des arm&#233;es&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;La victoire, la d&#233;route et la d&#233;faite&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Commandants-(Guerre).html&quot; title=&quot;Les commandants&quot;&gt;Les commandants&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;Les ressources des arm&#233;es&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Les pouvoirs sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exemples-Darm&#233;es-(Guerre).html&quot; title=&quot;Exemples d&amp;#39;arm&#233;es&quot;&gt;Exemples d&#39;arm&#233;es&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Optionnelles-Du-Combat-De-Masse-(Guerre).html&quot; title=&quot;Les r&#232;gles optionnelles du combat de masse&quot;&gt;Les r&#232;gles optionnelles du combat de masse&lt;/a&gt;&lt;/li&gt;
